// @ts-nocheck
/* eslint-disable */
/**
 * Supporting-document list engine. GENERATED by tools/sync-supporting-doc-list.mjs from web/pages/sales_document{,_2…_7}.xhtml + resources/support/{crm_list,sales_doc_list}.{css,js} — do not edit; change the script and run `npm run supporting-doc-list:sync`.
 *
 * The scripts of the Java list pages, same behaviour line by line: the toolbar of crm_list.js (the "sort by" menu and the sort of the rows, the filter
 * overlay), the inline script (the row menu, the search pill, the customer suggestions, the scroll set-up) and sales_doc_list.js (infinite scroll: the
 * next page of rows is asked for when the table is scrolled to its end, and added as <tr> rows that are the same markup as the ones the template draws).
 *
 * WHY it is imperative DOM code and not Angular components: the Java page adds rows to a table by writing HTML strings; porting it 1:1 is what
 * guarantees the screen and its states are those of the production system.
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java files (all of it lives in tools/sync-supporting-doc-list.mjs):
 *   - the environment is injected (SupportingDocListEnv): texts, navigation, the BFF contract (/board/sales-document-list), the family (cfg) — in Java these were EL, the URL and globals;
 *   - the seven pages are one: formType / subPage / acts / subId come from env.cfg, the links to the form are routes (env.route);
 *   - the inline handlers that built a Java address from the row (…face?…&quotation_id=<id>) are static (window.sdGo(this,'edit'), the id is read from the row);
 *   - fetch('../board/…') is env.fetch('/board/…'), the images are assets/images/…, the document listener is added through listen() and removed by destroy().
 */

export interface SupportingDocListEnv {
  /** commonBean.msg['key'] in the active language */
  t: (key: string) => string;
  /** the BFF contract of the page: GET /board/sales-document-list?formType=&page=&perPage= (answered by the host: mock or live) */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
  /** window.location.href = '<form>.face?…': the route of the form of this family (mode: edit | detail) */
  navigate: (route: string) => void;
  route: (id: string, mode: 'edit' | 'detail') => string;
  /** #{request.contextPath}: the base of the address odsProspectSuggest builds (…/board/prospect-list) */
  ctx: string;
  /**
   * attach the customer suggestions (odsProspectSuggest) to the search field. false = what Java does in practice: open_down_select.js is loaded after the
   * inline script, so the function does not exist yet when the script looks for it
   */
  suggestCustomers: boolean;
  /** the family: what differed in the seven Java pages */
  /** may the user use this button of the registry (PermissionService.canUse) */
  access: (code: string) => boolean;
  cfg: { formType: string; subPage: string; acts: number; subId: number; slug: string; detail: string };
}

export function startSupportingDocList(env: SupportingDocListEnv): () => void {
  var destroyed = false;
  var disposers = [];
  var timers = [];
  var observers = [];
  function listen(target, type, fn, opts) {
    target.addEventListener(type, fn, opts);
    disposers.push(function () { target.removeEventListener(type, fn, opts); });
  }
  function tmo(fn, ms) { var h = setTimeout(function () { if (!destroyed) { fn(); } }, ms); timers.push(h); return h; }
  function track(o) { observers.push(o); return o; }
  /* document.readyState / DOMContentLoaded / load of the page the script was written for (see the generator) */
  var readyState = 'loading';
  var readyQueue = [];
  var loadQueue = [];
  function onReady(fn) { if (readyState === 'loading') { readyQueue.push(fn); } else { tmo(fn, 0); } }
  function onLoad(fn) { if (readyState !== 'complete') { loadQueue.push(fn); } else { tmo(fn, 0); } }
  function runQueue(queue, type) {
    queue.splice(0).forEach(function (fn) {
      try { fn.call(type === 'load' ? window : document, new Event(type)); } catch (e) { console.error(e); }
    });
  }

  /* Nothing that is still in flight when the screen is left may repaint it: after destroy() a request never settles. */
  var rawFetch = env.fetch;
  var never = function () { return new Promise(function () {}); };
  var guardResponse = function (r) {
    return {
      ok: r.ok, status: r.status, statusText: r.statusText, headers: r.headers, url: r.url,
      clone: function () { return guardResponse(r.clone()); },
      json: function () { return r.json().then(function (v) { return destroyed ? never() : v; }); },
      text: function () { return r.text().then(function (v) { return destroyed ? never() : v; }); },
      blob: function () { return r.blob().then(function (v) { return destroyed ? never() : v; }); },
      arrayBuffer: function () { return r.arrayBuffer().then(function (v) { return destroyed ? never() : v; }); }
    };
  };
  env = Object.assign({}, env, {
    fetch: function (a, b) {
      if (destroyed) { return never(); }
      return rawFetch(a, b).then(
        function (r) { return destroyed ? never() : guardResponse(r); },
        function (e) { return destroyed ? never() : Promise.reject(e); });
    }
  });

  /* ---- the head: window.CT_I18N (the texts crm_list.js reads) ---- */
              /* i18n bridge — crm_list.js เป็นไฟล์ .js ธรรมดา อ่าน EL ไม่ได้ ส่งข้อความที่แปลแล้วผ่าน window.CT_I18N (ต้องมาก่อนโหลดสคริปต์) */
              var CT_I18N = {
                  sort_label:     env.t("label.contracts.sort_label"),
                  sort_date_desc: env.t("label.contracts.sort_date_desc"),
                  sort_date_asc:  env.t("label.contracts.sort_date_asc"),
                  sort_name_asc:  env.t("label.sd.sort_name_asc"),
                  sort_name_desc: env.t("label.sd.sort_name_desc")
              };

  /* ---- resources/support/crm_list.js ---- */
  (function () {
    "use strict";
  
      /* (ctx(): the context path of the Java app — images are assets/images/ here) */
      function parseDMY(s) {
          var m = (s || '').trim().match(/(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
          if (!m) { return 0; }
          var y = parseInt(m[3], 10); if (y < 100) { y += 2000; }
          return new Date(y, parseInt(m[2], 10) - 1, parseInt(m[1], 10)).getTime();
      }
  
      function cellText(row, selector) {
          var n = row.querySelector(selector);
          return n ? (n.textContent || '').trim() : '';
      }
  
      function sortRows(mode) {
          var tbody = document.getElementById('sdTableBody');
          if (!tbody) { return; }
          var rows = Array.prototype.slice.call(tbody.querySelectorAll('tr[data-name]'));
          rows.sort(function (a, b) {
              if (mode === 'date_desc' || mode === 'date_asc') {
                  var da = parseDMY(cellText(a, '.ct-date'));
                  var db = parseDMY(cellText(b, '.ct-date'));
                  return mode === 'date_desc' ? db - da : da - db;
              }
              var na = cellText(a, '.ct-name') || a.getAttribute('data-name') || '';
              var nb = cellText(b, '.ct-name') || b.getAttribute('data-name') || '';
              return mode === 'name_asc' ? na.localeCompare(nb, 'th') : nb.localeCompare(na, 'th');
          });
          rows.forEach(function (r) { tbody.appendChild(r); });
      }
  
      /* i18n: ข้อความมาจาก messages_<lang>.properties ผ่าน window.CT_I18N (หน้า list ตั้งค่าก่อนโหลดสคริปต์นี้)
         ถ้า bridge หายไป fallback เป็นข้อความไทยเดิม — หน้าไม่พัง */
      var I18N = CT_I18N;
      function t(key, fallback) { var v = I18N[key]; return v ? v : fallback; }
  
      function buildSortUI(right) {
          var itemStyle = 'padding:9px 12px;border-radius:8px;cursor:pointer;font-size:calc(14px + var(--fs-adj,0px));color:#374151;';
  
          var label = document.createElement('span');
          label.className = 'ct-sort-label';
          label.textContent = t('sort_label', 'จัดเรียง:');
  
          var box = document.createElement('div');
          box.style.position = 'relative';
          box.innerHTML =
              '<button class="ct-sort-btn" id="ctSortBtn" type="button">' +
              '  <img src="' + 'assets/images/icon/fi_sort_by.svg" alt="" style="width:16px;height:16px;object-fit:contain;"/>' +
              '  <span id="ctSortLabel">' + t('sort_date_desc', 'เรียงจากวันที่ล่าสุด') + '</span>' +
              '</button>' +
              '<div id="ctSortMenu" style="display:none;position:absolute;top:calc(100% + 6px);right:0;background:#fff;border:1px solid #E5E7EB;border-radius:10px;box-shadow:0 6px 24px rgba(0,0,0,.12);padding:6px;min-width:220px;z-index:60;">' +
              '  <div class="ct-sort-item" data-sort="date_desc" style="' + itemStyle + '">' + t('sort_date_desc', 'เรียงจากวันที่ล่าสุด') + '</div>' +
              '  <div class="ct-sort-item" data-sort="date_asc" style="' + itemStyle + '">' + t('sort_date_asc', 'เรียงจากวันที่เก่าสุด') + '</div>' +
              '  <div class="ct-sort-item" data-sort="name_asc" style="' + itemStyle + '">' + t('sort_name_asc', 'เรียงตามชื่อ (ก-ฮ)') + '</div>' +
              '  <div class="ct-sort-item" data-sort="name_desc" style="' + itemStyle + '">' + t('sort_name_desc', 'เรียงตามชื่อ (ฮ-ก)') + '</div>' +
              '</div>';
  
          // แทรกไว้หน้าสุด (ก่อนช่องค้นหา) → ลำดับ: จัดเรียง | ปุ่ม sort | ค้นหา | filter | เพิ่มใหม่
          right.insertBefore(box, right.firstChild);
          right.insertBefore(label, box);
  
          var btn = document.getElementById('ctSortBtn');
          var menu = document.getElementById('ctSortMenu');
          var labelTxt = document.getElementById('ctSortLabel');
  
          btn.addEventListener('click', function (e) {
              e.stopPropagation();
              menu.style.display = (menu.style.display === 'none' || !menu.style.display) ? 'block' : 'none';
          });
          Array.prototype.forEach.call(menu.querySelectorAll('.ct-sort-item'), function (it) {
              it.addEventListener('mouseenter', function () { it.style.background = '#F0F2FF'; });
              it.addEventListener('mouseleave', function () { it.style.background = ''; });
              it.addEventListener('click', function () {
                  labelTxt.textContent = it.textContent.trim();
                  sortRows(it.getAttribute('data-sort'));
                  menu.style.display = 'none';
              });
          });
          listen(document, 'click', function (e) {
              if (menu.style.display === 'block' && !menu.contains(e.target) && e.target !== btn && !btn.contains(e.target)) {
                  menu.style.display = 'none';
              }
          });
      }
  
      // ===== ตัวกรอง (filter): ผูกไอคอน ▽ เปิด overlay; apply/clear วิ่ง server-side ที่ bean =====
      function wireFilter() {
          var fbtn = document.getElementById('ctFilterBtn');
          var overlay = document.getElementById('sdFilterOverlay');
          if (!fbtn || !overlay || fbtn.getAttribute('data-wired')) { return; }
          fbtn.setAttribute('data-wired', '1');
          fbtn.style.cursor = 'pointer';
          fbtn.addEventListener('click', function (e) {
              e.stopPropagation();
              overlay.classList.add('show');
          });
          overlay.addEventListener('click', function (e) {
              if (e.target === overlay) { overlay.classList.remove('show'); }
          });
      }
      function sdCloseFilter() {
          var o = document.getElementById('sdFilterOverlay');
          if (o) { o.classList.remove('show'); }
      }
      window.sdCloseFilter = sdCloseFilter;
  
      function init() {
          var right = document.querySelector('.ct-topbar-right');
          if (right && !document.getElementById('ctSortBtn')) {
              buildSortUI(right);
              // เรียงเริ่มต้น: วันที่ล่าสุด (ให้ตรงกับ label)
              sortRows('date_desc');
          }
          wireFilter();
      }
  
      onReady(init);
  })();

  /* ---- resources/support/sales_doc_list.js ---- */
  (function () {
    "use strict";
      function g(id) { return document.getElementById(id); }
      function esc(s) {
          return (s == null ? "" : String(s)).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
      }
      /* ISO "yyyy-MM-dd" → "dd/MM/yyyy" — ตรงกับ Sales_DocumentBean DATE_PATTERN_VIEW ฝั่ง Java */
      function isoToView(iso) {
          if (!iso) { return ""; }
          var p = String(iso).split("-");
          return p.length === 3 ? (p[2] + "/" + p[1] + "/" + p[0]) : String(iso);
      }
      /* ต้องตรงกับ Sales_DocumentBean.getStatusDisplay()/getStatusClass() เป๊ะ (ฝั่ง Java) —
         แถวที่ JSF render (หน้าแรก) กับแถวที่ JS ต่อ (หน้าถัดไป) จะได้หน้าตาเหมือนกัน */
      function statusDisplay(s) {
          switch (s) {
              case "ACTIVE": return "สำเร็จ";
              case "WAIT_APPROVE": return "รออนุมัติ";
              case "REJECTED": return "ไม่อนุมัติ";
              case "new": return "สร้างใหม่";
              case "cancel": return "ยกเลิก";
              default: return s || "";
          }
      }
      function statusClass(s) {
          switch (s) {
              case "ACTIVE": return "status-success";
              case "WAIT_APPROVE": return "status-pending";
              case "REJECTED": case "cancel": return "status-rejected";
              case "new": return "status-new";
              default: return "status-pending";
          }
      }
  
      /**
       * cfg: { formType, subPage, pid, pageId, act, acts, subId, perPage, i18n:{edit,view} }
       * เรียกครั้งเดียวตอนเปิดหน้า (หลังหน้าแรก render จาก JSF แล้ว) หรือตอน clearFilters() เสร็จ
       * (กลับมาโหมด scroll — DOM ของ .ct-table-wrap ถูกแทนที่ใหม่ทั้งก้อนจาก ajax ต้อง bind ใหม่)
       */
      window.initSalesDocScroll = function (cfg) {
          var PER_PAGE = cfg.perPage || 20;
          var NEAR_END_PX = 300;
          var loading = false, done = false;
          var obs = null;
          /* ★ 14/09/2026 — เพดานกันโหลดอัตโนมัติ (fillIfShort) รัวไม่หยุด — user รายงานจาก log เห็นยิงไป
             ถึง page=120! (2,400 แถว) ในการเปิดหน้าครั้งเดียว ทั้งที่ตั้งใจให้ "เติมจนกว่าจะพอเลื่อนได้" เท่านั้น
             แปลว่าการเช็ค scrollHeight/clientHeight มีจังหวะที่วัดพลาด (เช่น เรียกเร็วเกินกว่า layout จะ reflow
             ทันทีหลัง insertAdjacentHTML) ทำให้เข้าใจผิดว่า "ยังไม่พอเลื่อน" ซ้ำ ๆ ไม่จบ — ใส่เพดานไว้กันเหตุ
             (10 หน้า = 200 แถว มากเกินพอสำหรับจอทั่วไปแน่นอน) เกินนี้ให้หยุดเติมเอง ปล่อยให้ scroll event/
             IntersectionObserver จริงของ user เป็นตัวสั่งโหลดต่อแทน (เชื่อถือได้กว่าเพราะมาจาก interaction จริง) */
          var AUTO_FILL_MAX = 10;
          var autoFillCount = 0;
          // หน้าแรก (page=1) มาจาก JSF (pagedQuotationList) ตอน SSR แล้ว — เริ่มนับจาก 1 ให้รอบถัดไปขอหน้า 2
          var page = 1;
          // ได้แถวหน้าแรกน้อยกว่า perPage อยู่แล้ว = ไม่มีหน้าถัดไปจริง ๆ ไม่ต้องเสียรอบไปขอเพิ่ม
          var initialRows = document.querySelectorAll('#sdTableBody tr[data-name]').length;
          if (initialRows > 0 && initialRows < PER_PAGE) { done = true; }
  
          function rowHtml(it) {
              var id = it.id;
              var avatar = it.customerAvatar
                  ? '<img src="' + esc(it.customerAvatar) + '" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" onerror="this.onerror=null;this.src=\'assets/images/icon/default_avatar.svg\';"/>'
                  : '<img src="assets/images/icon/default_avatar.svg" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:50%;"/>';
              return '<tr data-name="' + esc((it.customerName || '') + ' ' + (it.customerCode || '') + ' ' + (it.quotationNo || '')) + '" style="cursor:pointer;" ondblclick="window.sdGo(this,\'edit\')">'
                  + '<td onclick="event.stopPropagation();"><div style="display:flex; align-items:center; gap:10px;">'
                  +   '<div class="ct-ctx-wrap">'
                  +     '<i class="fas fa-ellipsis-v ct-menu-btn" onclick="window.sdCtxToggle(this.nextElementSibling.id.slice(6),event)"></i>'
                  +     '<div class="ct-ctx-menu" id="sdCtx-' + id + '">'
                  +       '<div class="ct-ctx-item" onclick="window.sdGo(this,\'edit\')">' + esc(cfg.i18n.edit) + '</div>'
                  +       (env.access(env.cfg.detail) ? '<div class="ct-ctx-item" onclick="window.sdGo(this,\'detail\')">' + esc(cfg.i18n.view) + '</div>' : '')
                  +     '</div>'
                  +   '</div>'
                  + '</div></td>'
                  + '<td class="ct-date">' + esc(isoToView(it.quotationDate)) + '</td>'
                  + '<td><div class="ct-name-wrap"><div class="ct-avatar">' + avatar + '</div><span class="ct-name">' + esc(it.customerName) + '</span></div></td>'
                  + '<td class="ct-code">' + esc(it.customerCode) + '</td>'
                  + '<td>' + esc(it.quotationNo) + '</td>'
                  + '<td><div class="ct-agent"><div class="ct-agent-av"><img src="assets/images/icon/default_avatar.svg" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" alt=""/></div><span class="ct-agent-txt">' + esc(it.salesperson) + '</span></div></td>'
                  + '<td class="ct-date">' + esc(isoToView(it.receiveDate)) + '</td>'
                  + '<td><span class="status-badge ' + statusClass(it.status) + '">' + esc(statusDisplay(it.status)) + '</span></td>'
                  + '</tr>';
          }
  
          function fetchNext() {
              if (loading || done) { return; }
              loading = true;
              var next = page + 1;
              env.fetch('/board/sales-document-list?formType=' + encodeURIComponent(cfg.formType) + '&page=' + next + '&perPage=' + PER_PAGE,
                    { credentials: 'same-origin' })
                  .then(function (r) { return r.ok ? r.json() : null; })
                  .then(function (resp) {
                      var result = (resp && resp.result) || {};
                      var items = result.items || [];
                      page = next;
                      if (items.length) {
                          var body = g('sdTableBody');
                          if (body) { body.insertAdjacentHTML('beforeend', items.map(rowHtml).join('')); }
                      }
                      done = items.length < PER_PAGE;
                  })
                  .catch(function (err) {
                      console.error('[sales_doc_list] โหลดหน้า ' + next + ' ไม่สำเร็จ:', err);
                      done = true;   // กันยิงซ้ำรัว ๆ ตอน backend ล่ม
                  })
                  .then(function () { loading = false; fillIfShort(); });
          }
  
          /* การ์ดตารางอาจสูงเกือบเต็มจอ แต่มีแค่ไม่กี่แถวจากหน้าแรก — ถ้ายังไม่ล้น (ไม่มี scrollbar ให้เลื่อน)
             จะไม่มีทาง trigger event "scroll" ได้เลย ต้องโหลดต่อเองจนกว่าจะเลื่อนได้จริงหรือข้อมูลหมดจริง
             (pattern เดียวกับ ctFillViewport ของ contracts.xhtml) */
          function fillIfShort() {
              var wrap = document.querySelector('.ct-table-wrap');
              if (!wrap || done || loading) { return; }
              if (autoFillCount >= AUTO_FILL_MAX) { return; }   // กันรัวไม่หยุด (ดูคอมเมนต์ที่ AUTO_FILL_MAX)
              if (wrap.scrollHeight <= wrap.clientHeight + NEAR_END_PX) {
                  autoFillCount++;
                  fetchNext();
              }
          }
  
          function bindScroll() {
              var wrap = document.querySelector('.ct-table-wrap');
              var sentinel = g('sdScrollSentinel');
              if (!wrap) { return; }
              if (window.IntersectionObserver && sentinel) {
                  if (obs) { obs.disconnect(); }
                  obs = track(new IntersectionObserver(function (entries) {
                      if (entries[0].isIntersecting) { fetchNext(); }
                  }, { root: wrap, rootMargin: NEAR_END_PX + 'px' }));
                  obs.observe(sentinel);
              }
              wrap.addEventListener('scroll', function () {
                  if (wrap.scrollTop + wrap.clientHeight >= wrap.scrollHeight - NEAR_END_PX) { fetchNext(); }
              });
          }
  
          bindScroll();
          fillIfShort();
      };
  })();

  /* ---- the inline script of sales_document*.xhtml ---- */
              /* ── เมนู 3 จุดต่อแถว (แก้ไข/ดู) — pattern เดียวกับ window.ctCtxToggle ของ contracts.xhtml
                 position:fixed วางที่ไอคอน หนีการ clip ของ .ct-table-wrap (overflow:auto) */
              /* (not in the Java file) the row menu and the double click: the Java rows wrote window.location.href = '<form>.face?…&action_type=edit|detail&quotation_id=<id>' into
                 each handler; the id is read from the row here and the host moves to the route of the form of this family */
              window.sdGo = function (el, mode) {
                  var row = el.closest('tr');
                  var menu = row ? row.querySelector('.ct-ctx-menu') : null;
                  env.navigate(env.route(menu ? menu.id.slice(6) : '', mode));
              };
              window.sdCtxToggle = function (id, e) {
                  e.stopPropagation();
                  document.querySelectorAll('.ct-ctx-menu').forEach(function (m) { m.classList.remove('show'); });
                  var menu = document.getElementById('sdCtx-' + id);
                  if (!menu) { return; }
                  var icon = e.currentTarget || e.target;
                  var r = icon.getBoundingClientRect();
                  menu.style.left = r.left + 'px';
                  menu.style.top = (r.bottom + 4) + 'px';
                  menu.classList.add('show');
                  var mr = menu.getBoundingClientRect();
                  if (mr.right > window.innerWidth - 8) { menu.style.left = (window.innerWidth - mr.width - 8) + 'px'; }
                  if (mr.bottom > window.innerHeight - 8) { menu.style.top = (r.top - mr.height - 4) + 'px'; }
              };
              listen(document, 'click', function () {
                  document.querySelectorAll('.ct-ctx-menu.show').forEach(function (m) { m.classList.remove('show'); });
              });
              (function () {
                  var box = document.getElementById('ldSearch');
                  var ic = box ? box.querySelector('.ld-search-ic') : null;
                  var input = document.getElementById('ldSearchInput');
                  var clr = document.getElementById('ldSearchClear');
                  var go = document.getElementById('ldSearchGo');
                  var empty = document.getElementById('sdEmptyRow');
                  if (!box || !input) { return; }
                  function rows() { return Array.prototype.slice.call(document.querySelectorAll('#sdTableBody tr[data-name]')); }
                  function applyFilter() {
                      var q = (input.value || '').trim().toLowerCase();
                      var shown = 0;
                      rows().forEach(function (tr) {
                          var name = (tr.getAttribute('data-name') || '').toLowerCase();
                          var ok = name.indexOf(q) !== -1;
                          tr.style.display = ok ? '' : 'none';
                          if (ok) { shown++; }
                      });
                      if (empty) { empty.style.display = (q !== '' && shown === 0) ? '' : 'none'; }
                  }
                  if (ic) { ic.addEventListener('click', function () { box.classList.toggle('open'); if (box.classList.contains('open')) { input.focus(); } }); }
                  input.addEventListener('input', applyFilter);
                  if (go) { go.addEventListener('click', function () { applyFilter(); }); }
                  input.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); applyFilter(); } });
                  if (clr) { clr.addEventListener('click', function () { input.value = ''; applyFilter(); box.classList.remove('open'); }); }
                  /* ★ 18/09: การ์ดแนะนำลูกค้าใต้ช่องค้นหา (component กลาง odsProspectSuggest, open_down_select.js)
                     เลือกแล้วใส่ชื่อลงช่อง + เรียก applyFilter() กรองแถวที่โหลดมาแล้วทันที (เหมือนพิมพ์เอง) */
                  if (env.suggestCustomers && window.odsProspectSuggest) {
                      odsProspectSuggest(input, {
                          contextPath: env.ctx,
                            fetch: env.fetch,
                          onPick: function (item) {
                              input.value = item && item.value ? item.value : input.value;
                              applyFilter();
                          }
                      });
                  }
              })();
              /* ★ 14/09/2026 — infinite scroll (sales_doc_list.js) เฉพาะโหมดปกติ (ไม่กรอง) — ค่าตาม
                 formType/acts/sub_id ของหน้านี้ (the family) เรียกครั้งแรกตอนเปิดหน้า
                 ที่นี่ + อีกครั้งตอน clearFilters() เสร็จ (ปุ่ม "ล้าง" ด้านบน, DOM ถูกแทนที่ใหม่) */
              window.sdInitScroll = function () {
                  if (window.initSalesDocScroll) {
                      window.initSalesDocScroll({
                          formType: env.cfg.formType, subPage: env.cfg.subPage,
                          pid: 1, pageId: 7, act: 7, acts: env.cfg.acts, subId: env.cfg.subId, perPage: 20,
                          i18n: { edit: env.t("label.ld2.edit"), view: env.t("label.contracts.view_detail_tip") }
                      });
                  }
              };
              window.sdInitScroll();

  /* the entry points of the inline handlers and of the window.* functions */
  
  var EXPORTED = ["sdCloseFilter","sdCtxToggle","sdGo","sdInitScroll","initSalesDocScroll"];

  /* "the document has been parsed": DOMContentLoaded handlers in the order they were registered, then "load" */
  readyState = 'interactive';
  runQueue(readyQueue, 'DOMContentLoaded');
  readyState = 'complete';
  tmo(function () { runQueue(loadQueue, 'load'); }, 0);

  return function destroy() {
    destroyed = true;
    disposers.splice(0).forEach(function (d) { d(); });
    timers.splice(0).forEach(function (h) { clearTimeout(h); });
    observers.splice(0).forEach(function (o) { o.disconnect(); });
    EXPORTED.forEach(function (n) { try { delete window[n]; } catch (e) { window[n] = undefined; } });
  };
}
